// Chapter 7 design theory exercises: closures, candidate keys, canonical covers, normal forms, BCNF and 3NF
// decompositions, lossless joins and dependency preservation. The problems are generated by K.Normal from fixed
// seeds (the same problem every time); the answer is entered in the design workbench and checked by K.Normal,
// which accepts any correct answer (any valid key list, cover or decomposition) and says what is wrong.
(function (root) {
  'use strict';
  const K = root.K;
  const C = K.Content;
  const N = K.Normal;
  if (!C || !N || !N.exercise) return;

  const PICKS = [
    ['closure', [2, 7, 13, 21]], ['keys', [1, 3, 13, 19]], ['cover', [1, 4, 9, 12]], ['normalForm', [7, 12, 43, 22]],
    ['bcnf', [2, 4, 6, 18]], ['3nf', [1, 6, 10, 16]], ['lossless', [8, 12, 19]], ['preservation', [1, 16, 22]],
  ];
  const TITLE = {
    closure: (x) => 'Closure of ' + x.given.attrs.join(''), keys: () => 'Candidate keys', cover: () => 'Canonical cover', normalForm: () => 'Highest normal form',
    bcnf: () => 'BCNF decomposition', '3nf': () => '3NF synthesis', lossless: () => 'Lossless or lossy?', preservation: () => 'Dependency preservation',
  };
  const HOW = {
    closure: 'Enter the closure as a list of attributes in the workbench.',
    keys: 'Enter every candidate key, separated by semicolons (for example AC; CD).',
    cover: 'Enter the dependencies of your canonical cover, one per line.',
    normalForm: 'Choose the highest of 1NF, 2NF, 3NF and BCNF that the schema satisfies.',
    bcnf: 'Enter the schemas of your decomposition, for example (A, B), (B, C, D). Any lossless decomposition into BCNF schemas is accepted.',
    '3nf': 'Enter the schemas of your decomposition. Any lossless, dependency-preserving decomposition into 3NF schemas is accepted.',
    lossless: 'Answer yes (lossless) or no (lossy).',
    preservation: 'Answer yes or no; if no, list the dependencies of F that are lost.',
  };

  function hints(kind, x) {
    const P = N.problem(x.schema, x.fds.map((f) => ({ lhs: f.lhs, rhs: f.rhs })));
    const set = (a) => (a.length ? a.join('') : '∅');
    let rhs = 0, lhs = 0;
    for (const f of P.fds) { rhs |= f.r & ~f.l; lhs |= f.l; }
    const core = N.names(P, P.all & ~rhs), never = N.names(P, P.all & rhs & ~lhs);
    switch (kind) {
      case 'closure': {
        const first = x.fds.find((f) => f.lhs.every((a) => x.given.attrs.includes(a)));
        return ['Start with result = ' + set(x.given.attrs) + ' and look for a dependency whose whole left side is inside the result.',
          first ? 'For example ' + first.text + ' applies at once: add ' + set(first.rhs) + '.' : 'No dependency applies at the start: then the closure is ' + set(x.given.attrs) + ' itself.',
          'Go round the list again after each addition, until a full pass adds nothing.'];
      }
      case 'keys':
        return ['A candidate key is a superkey (its closure is all of R) with no superkey inside it.',
          core.length ? set(core) + ' appear' + (core.length === 1 ? 's' : '') + ' on no right side, so ' + (core.length === 1 ? 'it is' : 'they are') + ' in every key.' : 'Every attribute appears on some right side, so no attribute is forced into every key.',
          (never.length ? set(never) + ' appear' + (never.length === 1 ? 's' : '') + ' only on right sides, so in no key. ' : '') + 'Try the small sets first and skip supersets of keys you have found.'];
      case 'cover':
        return ['Combine dependencies with the same left side (union rule) first.',
          'An attribute A of a left side αA is extraneous if the closure of α (under F) already contains the right side.',
          'An attribute of a right side is extraneous if the left side still determines it once the attribute is removed from that dependency; repeat until nothing changes.'];
      case 'normalForm':
        return ['Find the candidate keys first: the tests all depend on them.',
          'BCNF: is the left side of every nontrivial dependency a superkey? 3NF: if not, is every attribute on the right prime?',
          '2NF fails when a nonprime attribute depends on a proper part of a candidate key.'];
      case 'bcnf':
        return ['Find a dependency α → β whose left side is not a superkey of R.',
          'Replace R by (R − β) and (α ∪ β); both parts share α, which is a key of the second, so the split is lossless.',
          'Test each part again, with the dependencies that hold on it (from F+), until every part is in BCNF.'];
      case '3nf':
        return ['Start from a canonical cover of F.',
          'Make one schema α ∪ β for each dependency α → β of the cover.',
          'If no schema contains a candidate key of R, add one that is a key; then drop schemas contained in others.'];
      case 'lossless':
        return x.given.schemas.length === 2
          ? ['For two schemas: compute R1 ∩ R2.', 'The decomposition is lossless if R1 ∩ R2 → R1 or R1 ∩ R2 → R2 is in F+.', 'Compute the closure of R1 ∩ R2 and see whether it contains all of one schema.']
          : ['With more than two schemas, use the chase (tableau) test.', 'Write one row per schema: a_j where the schema has attribute j, b_ij elsewhere; then apply each dependency, equating rows that agree on its left side.', 'The decomposition is lossless if some row ends with only a\'s. The Lossless join tab plays the chase once you have answered.'];
      case 'preservation':
        return ['A dependency is preserved if it follows from the dependencies that hold on the separate schemas.',
          'For α → β: result = α; for each schema Ri, add (result ∩ Ri)+ ∩ Ri; repeat until it stops growing.',
          'α → β is preserved when β ends up inside the result. A dependency whose attributes all lie in one schema is preserved at once.'];
    }
    return [];
  }
  function refText(kind, x) {
    const a = x.answer;
    switch (kind) {
      case 'closure': return '(' + x.given.attrs.join('') + ')+ = ' + a.closure.join('');
      case 'keys': return a.keys.map((k) => k.join('')).join('; ');
      case 'cover': return a.fds.join('\n');
      case 'normalForm': return a.nf;
      case 'bcnf': case '3nf': return a.schemas.map((s) => '(' + s.join(', ') + ')').join(', ');
      case 'lossless': return a.lossless ? 'lossless' : 'lossy';
      case 'preservation': return a.preserved ? 'yes, every dependency is preserved' : 'no; lost: ' + a.lost.join(', ');
    }
    return '';
  }
  const FIELD = { closure: 'closure', keys: 'keys', cover: 'fds', normalForm: 'nf', bcnf: 'schemas', '3nf': 'schemas', lossless: 'lossless', preservation: 'preserved' };

  for (const [kind, seeds] of PICKS) {
    seeds.forEach((seed, i) => {
      let x;
      try { x = N.exercise(kind, seed); } catch (e) { return; }
      const id = 'nf-' + kind.toLowerCase() + '-' + (i + 1);
      const n = x.schema.attrs.length;
      const level = Math.min(3, (n <= 4 ? 1 : n <= 5 ? 2 : 3) + (['cover', 'bcnf', '3nf'].includes(kind) && n > 4 ? 1 : 0));
      C.exercise({
        id, chapter: 7, kind: 'design', db: null, level,
        title: TITLE[kind](x) + (kind === 'closure' ? '' : ' ' + (i + 1)), design: x,
        text: [
          x.prompt,
          HOW[kind],
          { view: 'design', label: 'Answer it in the design workbench', sel: { exercise: id } },
          { tip: 'The workbench loads the schema and its dependencies. The tab that would work this question out is covered until you have checked your answer; the other tabs are there to help.' },
        ],
        hints: hints(kind, x),
        ref: refText(kind, x),
        check() {
          const W = K.UI && K.UI.DesignWorkbench;
          const answer = W ? W.answer(id) : null;
          const v = answer && answer[FIELD[kind]];
          if (v === undefined || v === null || (typeof v === 'string' && !v.trim())) return { ok: false, message: 'There is no answer for this exercise yet. Open the design workbench (the button above), enter your answer at the top, and check again.' };
          const r = N.check(x, answer);
          const fb = r.feedback.filter((f) => f !== 'correct').map((f) => f[0].toUpperCase() + f.slice(1) + (/[.!?]$/.test(f) ? '' : '.'));
          return r.ok ? { ok: true, message: 'Your answer is right.', details: fb } : { ok: false, message: fb.shift() || 'The answer is not right yet.', details: fb };
        },
      });
    });
  }
})(typeof window !== 'undefined' ? window : globalThis);
